'use client'

import { useEffect, useState, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import Image from 'next/image'
import { Horizon } from '@stellar/stellar-sdk'
import { WalletCard } from '@/components/WalletCard'
import { TransferModal } from '@/components/TransferModal'
import { RFPViewer } from '@/components/RFPViewer'
import { getSession, clearSession } from '@/lib/session'
import { getKit } from '@/lib/kit'

type Tab = 'rfp' | 'wallet'

const HORIZON_URL = 'https://horizon-testnet.stellar.org'
const NATIVE_CONTRACT = process.env.NEXT_PUBLIC_NATIVE_TOKEN_CONTRACT!

export default function AppPage() {
  const router = useRouter()
  const [contractId, setContractId] = useState<string | null>(null)
  const [balance, setBalance] = useState<string | null>(null)
  const [balanceLoading, setBalanceLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<Tab>('rfp')
  const [showTransfer, setShowTransfer] = useState(false)

  useEffect(() => {
    const session = getSession()
    if (session) setContractId(session.contractId)
  }, [])

  const fetchBalance = useCallback(async (addr: string) => {
    setBalanceLoading(true)
    try {
      const server = new Horizon.Server(HORIZON_URL)
      const account = await server.loadAccount(addr)
      const native = account.balances.find((b) => b.asset_type === 'native')
      setBalance(native ? parseFloat(native.balance).toFixed(2) : '0.00')
    } catch {
      setBalance('—')
    } finally {
      setBalanceLoading(false)
    }
  }, [])

  useEffect(() => {
    if (contractId) fetchBalance(contractId)
  }, [contractId, fetchBalance])

  function handleDisconnect() {
    clearSession()
    router.replace('/')
  }

  async function handleTransfer(recipient: string, amount: string): Promise<void> {
    const kit = getKit()
    const session = getSession()
    if (!session) throw new Error('Session expired')
    await kit.transfer(NATIVE_CONTRACT, recipient, parseFloat(amount))
    if (contractId) await fetchBalance(contractId)
  }

  if (!contractId) return null

  return (
    <div className="min-h-screen flex flex-col" style={{ background: '#f0f4ff' }}>
      {/* Top bar */}
      <header className="flex items-center justify-between px-4 md:px-8 py-3 bg-white border-b border-slate-200 shadow-sm">
        <div className="flex items-center gap-3">
          <Image src="/logo1.jpeg" alt="SealPass" width={36} height={36} className="rounded-lg" />
          <span className="text-base font-bold hidden md:block" style={{ color: '#1a2e5c' }}>SealPass</span>
        </div>
        <button
          onClick={handleDisconnect}
          className="text-sm px-4 py-1.5 rounded-lg border font-medium transition-all hover:bg-slate-50"
          style={{ color: '#5472a0', borderColor: '#e2e8f0' }}
        >
          Disconnect
        </button>
      </header>

      <main className="flex-1 px-4 md:px-8 py-6 max-w-4xl mx-auto w-full">
        {/* Tabs */}
        <div className="flex gap-1 mb-6 bg-white rounded-xl p-1 w-fit shadow-sm border border-slate-200">
          {([['rfp', 'RFP Proposal'], ['wallet', 'Wallet']] as const).map(([tab, label]) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className="px-5 py-2 rounded-lg text-sm font-semibold transition-all"
              style={
                activeTab === tab
                  ? { background: '#2563eb', color: '#ffffff' }
                  : { color: '#5472a0' }
              }
            >
              {label}
            </button>
          ))}
        </div>

        {/* RFP Tab */}
        {activeTab === 'rfp' && (
          <div className="bg-white rounded-2xl p-6 md:p-8 shadow-sm border border-slate-200">
            <RFPViewer />
          </div>
        )}

        {/* Wallet Tab */}
        {activeTab === 'wallet' && (
          <div className="flex flex-col gap-6">
            <WalletCard contractId={contractId} balance={balance} loading={balanceLoading} />

            <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-200 flex flex-col gap-5">
              <div>
                <span className="text-xs font-semibold uppercase tracking-widest block mb-2" style={{ color: '#94a3b8' }}>Balance</span>
                {balanceLoading ? (
                  <div className="h-10 w-40 rounded-lg animate-pulse bg-slate-100" />
                ) : (
                  <span className="text-4xl font-bold" style={{ color: '#1a2e5c' }}>
                    {balance ?? '—'} <span className="text-xl" style={{ color: '#5472a0' }}>XLM</span>
                  </span>
                )}
              </div>

              <div className="flex items-center gap-3">
                <button
                  onClick={() => setShowTransfer(true)}
                  className="px-5 py-2.5 rounded-xl font-bold text-white text-sm transition-all shadow-sm"
                  style={{ background: '#2563eb' }}
                >
                  Send XLM
                </button>
                <button
                  onClick={() => fetchBalance(contractId)}
                  className="px-4 py-2.5 rounded-xl text-sm font-medium border transition-all hover:bg-slate-50"
                  style={{ color: '#5472a0', borderColor: '#e2e8f0' }}
                >
                  Refresh
                </button>
                <span className="text-xs px-2.5 py-1 rounded-full border font-medium" style={{ color: '#2563eb', borderColor: 'rgba(37,99,235,0.3)', background: '#eff6ff' }}>
                  Testnet
                </span>
              </div>
            </div>
          </div>
        )}
      </main>

      {showTransfer && (
        <TransferModal onClose={() => setShowTransfer(false)} onTransfer={handleTransfer} />
      )}
    </div>
  )
}
