'use client'

import { useState } from 'react'

interface WalletCardProps {
  contractId: string
  balance: string | null
  loading: boolean
}

export function WalletCard({ contractId, balance, loading }: WalletCardProps) {
  const [copied, setCopied] = useState(false)

  async function handleCopy() {
    await navigator.clipboard.writeText(contractId)
    setCopied(true)
    setTimeout(() => setCopied(false), 1500)
  }

  return (
    <div className="rounded-2xl p-px" style={{ background: 'linear-gradient(135deg, #1a2e5c, #2563eb, #7ba8d9)' }}>
      <div className="rounded-2xl p-6 flex flex-col gap-4" style={{ background: 'linear-gradient(135deg, #1a2e5c 0%, #243f7a 100%)' }}>
        <div className="flex items-center justify-between">
          <span className="text-xs font-semibold uppercase tracking-widest" style={{ color: '#7ba8d9' }}>Smart Account</span>
          <span className="text-xs px-2.5 py-0.5 rounded-full font-medium" style={{ color: '#2563eb', background: '#eff6ff' }}>Testnet</span>
        </div>

        <div className="flex items-center gap-3">
          <span className="font-mono text-xs flex-1 truncate" style={{ color: '#aecbef' }}>{contractId}</span>
          <button
            onClick={handleCopy}
            className="text-xs px-2.5 py-1 rounded-lg border transition-all shrink-0 font-medium"
            style={{ color: copied ? '#7ba8d9' : '#aecbef', borderColor: 'rgba(174,203,239,0.3)' }}
          >
            {copied ? 'Copied!' : 'Copy'}
          </button>
        </div>

        <div>
          <span className="text-xs block mb-1" style={{ color: '#7ba8d9' }}>Balance</span>
          {loading ? (
            <div className="h-8 w-32 rounded-lg animate-pulse" style={{ background: 'rgba(255,255,255,0.08)' }} />
          ) : (
            <span className="text-3xl font-bold text-white">
              {balance ?? '—'} <span className="text-lg" style={{ color: '#7ba8d9' }}>XLM</span>
            </span>
          )}
        </div>
      </div>
    </div>
  )
}
