'use client'

import { useState } from 'react'

interface TransferModalProps {
  onClose: () => void
  onTransfer: (recipient: string, amount: string) => Promise<void>
}

export function TransferModal({ onClose, onTransfer }: TransferModalProps) {
  const [recipient, setRecipient] = useState('')
  const [amount, setAmount] = useState('')
  const [status, setStatus] = useState<'idle' | 'pending' | 'success' | 'error'>('idle')
  const [error, setError] = useState<string | null>(null)

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    setStatus('pending')
    setError(null)
    try {
      await onTransfer(recipient, amount)
      setStatus('success')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Transfer failed')
      setStatus('error')
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center px-4">
      <div className="absolute inset-0 backdrop-blur-sm bg-slate-900/40" onClick={onClose} />
      <div className="relative z-10 bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl border border-slate-200">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-lg font-bold" style={{ color: '#1a2e5c' }}>Send XLM</h2>
          <button onClick={onClose} className="text-xl leading-none text-slate-400 hover:text-slate-600 transition-colors">×</button>
        </div>

        {status === 'success' ? (
          <div className="text-center py-8">
            <div className="text-4xl mb-3">✅</div>
            <p className="font-bold text-lg mb-1" style={{ color: '#1a2e5c' }}>Transfer submitted</p>
            <p className="text-sm text-slate-500">Transaction signed and sent to the network</p>
            <button
              onClick={onClose}
              className="mt-6 w-full py-2.5 rounded-xl font-bold text-white transition-all"
              style={{ background: '#2563eb' }}
            >
              Done
            </button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div>
              <label className="block text-xs font-semibold mb-1.5 uppercase tracking-wide text-slate-500">
                Recipient Address
              </label>
              <input
                type="text"
                value={recipient}
                onChange={(e) => setRecipient(e.target.value)}
                placeholder="G… or C…"
                required
                className="w-full rounded-xl px-3 py-2.5 font-mono text-sm border border-slate-200 outline-none transition-colors focus:border-blue-400 bg-slate-50 placeholder-slate-300"
                style={{ color: '#1a2e5c' }}
              />
            </div>

            <div>
              <label className="block text-xs font-semibold mb-1.5 uppercase tracking-wide text-slate-500">
                Amount (XLM)
              </label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                min="0.0000001"
                step="any"
                required
                className="w-full rounded-xl px-3 py-2.5 text-sm border border-slate-200 outline-none transition-colors focus:border-blue-400 bg-slate-50 placeholder-slate-300"
                style={{ color: '#1a2e5c' }}
              />
            </div>

            {error && (
              <p className="text-sm text-red-600 bg-red-50 rounded-lg px-3 py-2 border border-red-100">{error}</p>
            )}

            <button
              type="submit"
              disabled={status === 'pending'}
              className="w-full py-2.5 rounded-xl font-bold text-white mt-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm"
              style={{ background: '#2563eb' }}
            >
              {status === 'pending' ? 'Signing with passkey…' : '🔑 Sign with Passkey'}
            </button>
          </form>
        )}
      </div>
    </div>
  )
}
